// window-join two keyed streams whose watermarks align
function* alignedFanIn<K,A,B>(s1: Iterable<[K,A]>, s2: Iterable<[K,B]>, windowMs: number) {
  const buf = new Map<K,{a:A|null,b:B|null,ts:number}>();
  for (const [k,v] of [...s1, ...s2]) {
    const e = buf.get(k) ?? {a:null,b:null,ts:Date.now()};
    if (s1 && v !== undefined) e.a = v as A;
    else e.b = v as B;
    if (e.a && e.b && Date.now()-e.ts >= windowMs) {
      yield [k, e.a, e.b] as [K,A,B];
      buf.delete(k);
    }
  }
}
